import { ICON_AREAS, ICON_KEYS, ICON_KEY_LIST } from "./keys";
import { ICONOIR } from "./sets/iconoir";
import { PHOSPHOR } from "./sets/phosphor";

// The text of `KEYS.md`, from the key table and the family maps. `bun scripts/glyph-keys.ts` writes the
// file and `keys.test.ts` fails when the file on disk is not this text.

function cell(name: string | null): string {
  return name === null ? "(lucide)" : `\`${name}\``;
}

export function keysMarkdown(): string {
  const lines = [
    "# Icon keys",
    "",
    "Generated by `bun scripts/glyph-keys.ts` from `keys.ts` and `sets/`. Do not edit by hand.",
    "",
    "Every glyph the app draws is named by what it means. A theme's `glyphs` picks the set that draws",
    "them (ADR 0137). A family with no fitting glyph for a key draws the lucide one, shown as `(lucide)`.",
    "Phosphor's three sets share one map; the fill and duotone files add `-fill` and `-duotone`.",
    "",
    `${ICON_KEY_LIST.length} keys.`,
  ];
  for (const [area, title] of Object.entries(ICON_AREAS)) {
    const keys = ICON_KEY_LIST.filter((key) => ICON_KEYS[key].area === area);
    if (keys.length === 0) continue;
    lines.push("", `## ${title}`, "", "| key | meaning | lucide | phosphor | iconoir |", "| --- | --- | --- | --- | --- |");
    for (const key of keys) {
      const row = ICON_KEYS[key];
      lines.push(`| \`${key}\` | ${row.meaning} | \`${row.lucide}\` | ${cell(PHOSPHOR[key])} | ${cell(ICONOIR[key])} |`);
    }
  }
  return `${lines.join("\n")}\n`;
}
